def test_window_pooled_and_group_metrics():
    assert conversions_in_window([2, 1, 3], 2) == 4
    assert conversions_in_window([2, 1], 5) == 3
    assert conversions_in_window([2, 1], 0) == 0
    groups = {"z": [], "b": [{"converted": True}], "a": [{"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5
    assert conversion_rate_by_group(groups) == {"a": 0.0, "b": 1.0, "z": None}
    assert top_converting_groups(groups, 5) == ["b", "a"]


def test_campaign_summary_uses_three_decimal_rate_and_nonempty_groups():
